{
  "microservices": [
    {
      "microservice_name": "Shipment Management",
      "responsibility": "Handles shipment registration, initiation, and operational management, including unique tracking identifier assignment, origin/destination validation, and consolidated administrative views.",
      "communicates_with": [
        "Routing and Planning",
        "Logistics Event Processing",
        "Monitoring and Tracking"
      ]
    },
    {
      "microservice_name": "Routing and Planning",
      "responsibility": "Manages route planning, candidate route retrieval, route validation, trip replanning, and route association with shipments.",
      "communicates_with": [
        "Shipment Management",
        "Logistics Event Processing"
      ]
    },
    {
      "microservice_name": "Logistics Event Processing",
      "responsibility": "Records and validates logistics events (receipt, loading, unloading, customs clearance, pickup), updates shipment status, recalculates transport status, and handles event intake from multiple channels.",
      "communicates_with": [
        "Shipment Management",
        "Routing and Planning",
        "Monitoring and Tracking"
      ]
    },
    {
      "microservice_name": "Monitoring and Tracking",
      "responsibility": "Provides shipment lookup by tracking identifier, current status, last known location, estimated arrival time, event history, and geographic view.",
      "communicates_with": [
        "Shipment Management",
        "Logistics Event Processing"
      ]
    }
  ]
}

{
  "microservices": [
    {
      "microservice_name": "Shipment Registration",
      "responsibility": "Handles registration of new shipments with origin, destination, and mandatory delivery deadline; assigns unique tracking identifiers; validates that origin and destination differ and are selected from registered logistics locations; supports registration before a route is defined.",
      "communicates_with": [
        "Routing and Planning"
      ]
    },
    {
      "microservice_name": "Operational Shipment Management",
      "responsibility": "Provides consolidated administrative views of shipments grouped by business status (unrouted, routed and in transit, collected by recipient); allows opening shipment details; tracks routed but uncollected shipments as in transit.",
      "communicates_with": [
        "Shipment Registration",
        "Routing and Planning",
        "Logistics Event Processing"
      ]
    },
    {
      "microservice_name": "Routing and Planning",
      "responsibility": "Manages route planning, candidate route retrieval, route validation against origin/destination/deadline, route association with shipments, identification of unrouted shipments, and trip replanning including destination changes and reassessment of routes for deviated shipments.",
      "communicates_with": [
        "Shipment Registration",
        "Route Computation",
        "Logistics Event Processing"
      ]
    },
    {
      "microservice_name": "Route Computation",
      "responsibility": "Provides route computation and candidate route retrieval via a pathfinder API, returning feasible routes based on origin, destination, and constraints.",
      "communicates_with": [
        "Routing and Planning"
      ]
    },
    {
      "microservice_name": "Logistics Event Processing",
      "responsibility": "Records and validates logistics events (receipt, loading, unloading, customs clearance, pickup); enforces event association with existing shipment, location, and trip where required; rejects invalid events; updates shipment operational status and recalculates transport status, known location, expected next step, and plan adherence; marks off-route, arrival, and completion states.",
      "communicates_with": [
        "Shipment Registration",
        "Routing and Planning",
        "Monitoring and Tracking"
      ]
    },
    {
      "microservice_name": "Channel Integration",
      "responsibility": "Handles channel-specific intake of logistics events from operational interface, integration service, and input-file processing; performs format validation and forwards valid events to Logistics Event Processing; ensures uniform application of business rules across channels.",
      "communicates_with": [
        "Logistics Event Processing"
      ]
    },
    {
      "microservice_name": "Monitoring and Tracking",
      "responsibility": "Provides read-only shipment lookup by tracking identifier, current status, last known location, estimated arrival time, event history, and geographic view; consumes authoritative status and location state from Logistics Event Processing without independently recalculating status.",
      "communicates_with": [
        "Logistics Event Processing"
      ]
    }
  ]
}

